def cycle_length(head):
    slow = fast = head
    while fast and fast.next:
        slow, fast = slow.next, fast.next.next
        if slow is fast:
            n, cur = 1, slow.next
            while cur is not slow:
                n += 1
                cur = cur.next
            return n
    return 0
```

